#include <stdio.h>
#include <stdint.h>

#define HBITS 20
#define HSIZE (1u << HBITS)
#define HMASK (HSIZE - 1u)

static uint64_t table[HSIZE];
static char S[10000][12];

/*
 * Codificacao exata (injetiva) de uma string curta + tipo, em 64 bits:
 *   tag (5 bits efetivos): 0 = string completa (len 10);
 *                          1..9  = PREFIXO de comprimento L (tag = L);
 *                          10..18 = SUFIXO de comprimento L (tag = 9 + L).
 *   len (bits 50..53): comprimento da subcadeia (1..10);
 *   val (bits 0..49): 5 bits por letra ('a'..'z' -> 0..25), ate 10 letras.
 */
static inline uint64_t make_key(int tag, int len, const char *s) {
    uint64_t val = 0;
    for (int i = 0; i < len; i++)
        val = (val << 5) | (uint64_t)(s[i] - 'a');
    return ((((uint64_t)tag << 4) | (uint64_t)len) << 50) | val;
}

/* Sondagem linear; retorna 1 se presente. Se insert=1 e ausente, insere. */
static inline int probe(uint64_t key, int insert) {
    uint64_t h = key * 0x9E3779B97F4A7C15ull;
    uint32_t idx = (uint32_t)(h >> (64 - HBITS));
    for (;;) {
        uint64_t cur = table[idx];
        if (cur == key) return 1;
        if (cur == 0) {
            if (insert) table[idx] = key;
            return 0;
        }
        idx = (idx + 1) & HMASK;
    }
}

int main(void) {
    int n, i, k, p, L;
    if (scanf("%d", &n) != 1) return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%11s", S[i]) != 1) return 0;
    }

    for (k = 0; k < n; k++) {
        int bad = 0;

        /* Caso q = 0 ou q = 10: S_k coincide com alguma string anterior. */
        if (probe(make_key(0, 10, S[k]), 0))
            bad = 1;

        /* Caso 1 <= q <= 9: S_k cruza a fronteira de S_a S_b.
         * Com recorte q = p:
         *   - o prefixo de S_k de comprimento 10-p deve igualar o SUFIXO
         *     de comprimento 10-p de alguma string anterior (S_a);
         *   - o sufixo de S_k de comprimento p deve igualar o PREFIXO
         *     de comprimento p de alguma string anterior (S_b).
         * Ambas as verificacoes usam o mesmo recorte p (necessario e suficiente).
         */
        for (p = 1; p <= 9 && !bad; p++) {
            if (probe(make_key(9 + (10 - p), 10 - p, S[k]), 0) &&   /* tag de sufixo len 10-p */
                probe(make_key(p, p, S[k] + (10 - p)), 0))          /* tag de prefixo len p   */
                bad = 1;
        }

        if (bad) {
            puts(S[k]);
            return 0;
        }

        /* Insere S_k e todos os seus prefixos/sufixos proprios nos conjuntos. */
        probe(make_key(0, 10, S[k]), 1);
        for (L = 1; L <= 9; L++) {
            probe(make_key(L, L, S[k]), 1);                /* prefixo de comprimento L */
            probe(make_key(9 + L, L, S[k] + (10 - L)), 1); /* sufixo  de comprimento L */
        }
    }

    puts("ok");
    return 0;
}
